arguments.command:
cat << 'EOF' > /app/build.py
import json

with open('/app/benchmark/source_data.json', 'r') as f:
    data = json.load(f)

# Extract data
research = data['research_milestones']['data']
industry = data['industry_milestones']['data']
regulatory = data['regulatory_milestones']['data']
investment = data['global_ai_investment']['data']

# Add track info
for d in research: d['track'] = 'Research'
for d in industry: d['track'] = 'Industry'
for d in regulatory: d['track'] = 'Regulatory'

milestones = research + industry + regulatory

html_content = f"""<!DOCTYPE html>
<html lang="en" class="theme-dark">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>AI Three-Track Timeline</title>
  <link href="/app/libs/fonts/inter.css" rel="stylesheet">
  <script src="/app/libs/d3.min.js"></script>
  <style>
    *, *::before, *::after {{ box-sizing: border-box; margin: 0; padding: 0; }}
    html.theme-dark {{
      --bg: #0A0A0A; --surface: #141414; --surface-hover: #1C1C1C;
      --border: rgba(255,255,255,0.04);
      --text: #EDEDED; --text-secondary: #888;
      --accent: #3b82f6; --accent-secondary: #8b5cf6;
      --positive: #10b981; --negative: #f43f5e; --warning: #f59e0b;
    }}
    body {{
      font-family: 'Inter', sans-serif;
      background: var(--bg); color: var(--text);
      width: 1920px; height: 1080px; overflow: hidden;
      display: flex; flex-direction: column;
    }}
    header {{ padding: 60px 80px 20px; }}
    h1 {{ font-size: 48px; font-weight: 700; letter-spacing: -0.03em; margin-bottom: 16px; }}
    p.subtitle {{ font-size: 20px; color: var(--text-secondary); max-width: 1200px; line-height: 1.5; }}
    #chart-container {{ flex: 1; position: relative; padding: 0 40px; }}
    svg {{ width: 100%; height: 100%; }}

    .track-line {{ stroke: var(--border); stroke-width: 2; }}
    .track-label {{ fill: var(--text-secondary); font-size: 16px; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; }}

    .bar {{ fill: rgba(59, 130, 246, 0.1); rx: 4; ry: 4; }}
    .bar-hover {{ fill: rgba(59, 130, 246, 0.2); }}
    .bar-label {{ fill: var(--accent); font-size: 14px; font-weight: 600; text-anchor: middle; }}

    .node-research {{ fill: var(--accent); }}
    .node-industry {{ fill: var(--accent-secondary); }}
    .node-regulatory {{ fill: var(--positive); }}

    .label {{ font-size: 13px; fill: var(--text); font-weight: 400; }}
    .label-bg {{ fill: var(--bg); fill-opacity: 0.8; }}

    .axis text {{ fill: var(--text-secondary); font-size: 16px; font-family: 'Inter'; }}
    .axis path, .axis line {{ stroke: var(--border); }}

    .chatgpt-line {{ stroke: var(--warning); stroke-width: 2; stroke-dasharray: 6 4; }}
    .chatgpt-label {{ fill: var(--warning); font-size: 16px; font-weight: 600; }}

    .legend text {{ fill: var(--text-secondary); font-size: 16px; }}
  </style>
</head>
<body>
  <header>
    <h1>The AI Compression: 2010–2024</h1>
    <p class="subtitle">As global private AI investment surged, the lag between <strong>Research Breakthroughs</strong>, <strong>Industry Adoption</strong>, and <strong>Regulatory Action</strong> compressed dramatically. The launch of ChatGPT in late 2022 marked a critical inflection point, shifting the ecosystem from sparse milestones to dense, near-simultaneous advancement across all three tracks.</p>
  </header>
  <div id="chart-container">
    <svg id="viz"></svg>
  </div>

  <script>
    const milestones = {json.dumps(milestones)};
    const investment = {json.dumps(investment)};

    const svg = d3.select("#viz");
    const width = 1840;
    const height = 860;
    const margin = {{top: 40, right: 60, bottom: 60, left: 180}};

    const innerWidth = width - margin.left - margin.right;
    const innerHeight = height - margin.top - margin.bottom;

    const g = svg.append("g").attr("transform", `translate(${{margin.left}},${{margin.top}})`);

    // Scales
    const xScale = d3.scaleLinear()
      .domain([2010, 2024.9])
      .range([0, innerWidth]);

    const yScale = d3.scaleBand()
      .domain(["Regulatory", "Industry", "Research"])
      .range([0, innerHeight * 0.75])
      .padding(0.5);

    const investScale = d3.scaleLinear()
      .domain([0, 120])
      .range([innerHeight, innerHeight * 0.3]);

    // Investment Bars
    const barWidth = innerWidth / 15 * 0.6;
    g.selectAll(".bar")
      .data(investment)
      .enter().append("rect")
      .attr("class", "bar")
      .attr("x", d => xScale(d.year + 0.5) - barWidth/2)
      .attr("y", d => investScale(d.investment_bn_usd))
      .attr("width", barWidth)
      .attr("height", d => innerHeight - investScale(d.investment_bn_usd))
      .attr("rx", 6);

    g.selectAll(".bar-label")
      .data(investment)
      .enter().append("text")
      .attr("class", "bar-label")
      .attr("x", d => xScale(d.year + 0.5))
      .attr("y", d => investScale(d.investment_bn_usd) - 8)
      .text(d => "$" + d.investment_bn_usd + "B");

    // X Axis
    const xAxis = d3.axisBottom(xScale)
      .tickValues(d3.range(2010, 2025))
      .tickFormat(d3.format("d"));

    g.append("g")
      .attr("class", "axis")
      .attr("transform", `translate(0,${{innerHeight}})`)
      .call(xAxis);

    // Track lines
    yScale.domain().forEach(track => {{
      g.append("line")
        .attr("class", "track-line")
        .attr("x1", 0).attr("x2", innerWidth)
        .attr("y1", yScale(track) + yScale.bandwidth()/2)
        .attr("y2", yScale(track) + yScale.bandwidth()/2);

      g.append("text")
        .attr("class", "track-label")
        .attr("x", -20)
        .attr("y", yScale(track) + yScale.bandwidth()/2)
        .attr("dy", "0.32em")
        .attr("text-anchor", "end")
        .text(track);
    }});

    // ChatGPT Line
    const chatgptX = xScale(2022 + 11/12);
    g.append("line")
      .attr("class", "chatgpt-line")
      .attr("x1", chatgptX).attr("x2", chatgptX)
      .attr("y1", 0).attr("y2", innerHeight);

    g.append("text")
      .attr("class", "chatgpt-label")
      .attr("x", chatgptX + 10)
      .attr("y", 20)
      .text("ChatGPT Launch (Nov '22)");

    // Nodes
    const nodes = milestones.map(d => ({{
      ...d,
      x: xScale(d.year + (d.month - 1)/12),
      y: yScale(d.track) + yScale.bandwidth()/2,
      colorClass: `node-${{d.track.toLowerCase()}}`
    }}));

    // Collision detection for labels
    // We will use a force simulation just for the labels to push them apart vertically
    const labels = nodes.map(d => ({{ ...d, labelY: d.y + (Math.random() > 0.5 ? 20 : -20) }}));

    const simulation = d3.forceSimulation(labels)
      .force("x", d3.forceX(d => d.x).strength(1))
      .force("y", d3.forceY(d => d.y).strength(0.05))
      .force("collide", d3.forceCollide(14).iterations(4))
      .stop();

    for (let i = 0; i < 300; ++i) simulation.tick();

    // Draw links from node to label
    g.selectAll(".link")
      .data(labels)
      .enter().append("line")
      .attr("stroke", "var(--border)")
      .attr("stroke-width", 1)
      .attr("x1", d => d.x)
      .attr("y1", d => d.y)
      .attr("x2", d => d.x)
      .attr("y2", d => d.y < d.labelY ? d.labelY - 10 : d.labelY + 10);

    // Draw Nodes
    g.selectAll(".node")
      .data(nodes)
      .enter().append("circle")
      .attr("class", d => d.colorClass)
      .attr("cx", d => d.x)
      .attr("cy", d => d.y)
      .attr("r", 6)
      .attr("stroke", "var(--bg)")
      .attr("stroke-width", 2);

    // Draw Labels
    const labelGroups = g.selectAll(".label-group")
      .data(labels)
      .enter().append("g")
      .attr("transform", d => `translate(${{d.x}},${{d.labelY}})`);

    labelGroups.append("text")
      .attr("class", "label")
      .attr("text-anchor", "middle")
      .attr("dy", "0.32em")
      .text(d => d.event)
      .each(function(d) {{
        const bbox = this.getBBox();
        d.bbox = bbox;
      }});

    labelGroups.insert("rect", "text")
      .attr("class", "label-bg")
      .attr("x", d => d.bbox.x - 4)
      .attr("y", d => d.bbox.y - 2)
      .attr("width", d => d.bbox.width + 8)
      .attr("height", d => d.bbox.height + 4)
      .attr("rx", 2);

    // Legend
    const legend = svg.append("g").attr("transform", `translate(${{width - 250}}, 40)`);

    const legendData = [
      {{ label: "Research Breakthroughs", color: "var(--accent)" }},
      {{ label: "Industry Adoption", color: "var(--accent-secondary)" }},
      {{ label: "Regulatory Action", color: "var(--positive)" }},
      {{ label: "Global AI Investment", color: "rgba(59, 130, 246, 0.3)" }}
    ];

    const legendItems = legend.selectAll(".legend-item")
      .data(legendData)
      .enter().append("g")
      .attr("transform", (d, i) => `translate(0, ${{i * 30}})`);

    legendItems.append("circle")
      .attr("cx", 0)
      .attr("cy", 0)
      .attr("r", 6)
      .attr("fill", d => d.color);

    legendItems.append("text")
      .attr("x", 16)
      .attr("y", 0)
      .attr("dy", "0.32em")
      .attr("class", "label")
      .style("font-size", "14px")
      .text(d => d.label);

  </script>
</body>
</html>
"""

with open('/app/output/index.html', 'w') as f:
    f.write(html_content)
EOF
python3 /app/build.py
